import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const canvas = document.querySelector('#scene');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.7));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.16;
const scene = new THREE.Scene();
scene.background = new THREE.Color('#08131d');
scene.fog = new THREE.FogExp2('#08131d', 0.011);
const camera = new THREE.PerspectiveCamera(54, 1, 0.1, 160);
scene.add(new THREE.HemisphereLight('#a9d8e9', '#14202a', 2.0));
const keyLight = new THREE.DirectionalLight('#e5f7ff', 3.1);
keyLight.position.set(-11, 23, 8); keyLight.castShadow = true;
keyLight.shadow.mapSize.set(1536, 1536); keyLight.shadow.camera.left = -35; keyLight.shadow.camera.right = 35; keyLight.shadow.camera.top = 40; keyLight.shadow.camera.bottom = -40; keyLight.shadow.bias = -0.0004;
scene.add(keyLight);
const cyanLight = new THREE.PointLight('#38def0', 65, 27, 2); cyanLight.position.set(-12, 4, 0); scene.add(cyanLight);
const orangeLight = new THREE.PointLight('#ff8c43', 65, 27, 2); orangeLight.position.set(12, 4, 0); scene.add(orangeLight);

const mat = (color, roughness=.65, metalness=.05, extra={}) => new THREE.MeshStandardMaterial({ color, roughness, metalness, ...extra });
const M = { turf:mat('#172c32',.88), stripe:mat('#28434a',.9), line:mat('#bed3cf',.45,0,{emissive:'#405650',emissiveIntensity:.3}), dark:mat('#0a141c',.66,.35), trim:mat('#354b54',.55,.65), white:mat('#dce9ea',.48,.2), ball:mat('#e4e9e9',.43,.18), black:mat('#18242b',.58,.22), cyan:mat('#22c8df',.3,.32,{emissive:'#098ea5',emissiveIntensity:.28}), orange:mat('#ff8641',.33,.22,{emissive:'#b14412',emissiveIntensity:.22}), glass:mat('#0b2632',.2,.35,{emissive:'#0b5260',emissiveIntensity:.25}), glowC:mat('#53efff',.28,.25,{emissive:'#26d8ed',emissiveIntensity:2}), glowO:mat('#ffae60',.3,.2,{emissive:'#ff681e',emissiveIntensity:1.6}) };
const boxGeo = new THREE.BoxGeometry(1,1,1);
const sphereGeo = new THREE.SphereGeometry(1,32,24);
const arena = new THREE.Group(); scene.add(arena);
function mesh(geometry, material, parent, x=0,y=0,z=0, sx=1,sy=1,sz=1){ const o=new THREE.Mesh(geometry,material); o.position.set(x,y,z); o.scale.set(sx,sy,sz); o.castShadow=true; o.receiveShadow=true; parent.add(o); return o; }
function box(parent,material,x,y,z,sx,sy,sz){return mesh(boxGeo,material,parent,x,y,z,sx,sy,sz)}
function cylinder(parent,material,r1,r2,h,x,y,z,segments=16){const o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}

// A contained arena with luminous goal mouths and a hand-built grandstand.
box(arena,M.turf,0,-.55,0,29,.8,49);
for(let i=0;i<32;i++){
  const z=-23.2+i*1.5; const c=i%2?M.turf:M.stripe;
  box(arena,c,0,-.13,z,26.8,.025,1.48);
}
box(arena,M.line,0,-.09,0,26.2,.035,.095);
box(arena,M.line,-13.1,-.09,0,.09,.035,45.2); box(arena,M.line,13.1,-.09,0,.09,.035,45.2);
for(const z of [-20,20]) box(arena,M.line,0,-.085,z,26.2,.04,.11);
// center circle and restrained field markings
const circle=new THREE.Mesh(new THREE.TorusGeometry(4,.055,6,72),M.line);circle.rotation.x=Math.PI/2;circle.position.y=-.065;arena.add(circle);
cylinder(arena,M.line,.13,.13,.025,0,-.05,0,24);
for(const x of [-9,-6,-3,3,6,9]) for(const z of [-16,-9,9,16]) cylinder(arena,M.trim,.13,.13,.035,x,-.08,z,12);
// boundary walls / transparent-feeling net foundations
for(const x of [-13.7,13.7]) { box(arena,M.dark,x,1.3,0,.85,3,47); for(let y=1;y<3.1;y+=.42) box(arena,M.trim,x,y,0,.91,.035,46); }
for(const z of [-23.4,23.4]) {box(arena,M.dark,0,1.25,z,27.8,2.7,.65);for(let x=-13;x<=13;x+=1.2) box(arena,M.trim,x,1.3,z,.025,2.4,.7);}
// end goal tunnels open toward the pitch
const goalParts=[];
function makeGoal(z,color,glow){
  const g=new THREE.Group(); g.position.z=z; arena.add(g); goalParts.push({group:g,glow});
  const sign=z<0?-1:1, frame=mat(color,.28,.35,{emissive:color,emissiveIntensity:.5});
  box(g,frame,-4.4,1.65,0,.22,3.3,.25); box(g,frame,4.4,1.65,0,.22,3.3,.25); box(g,frame,0,3.25,0,8.9,.22,.25);
  for(let d=0;d<4;d++) {const zz=sign*(.7+d*.65); for(const x of [-4.25,4.25])box(g,M.trim,x,1.48,zz,.035,2.95,.035);box(g,M.trim,0,2.95,zz,8.5,.035,.035);}
  box(g,mat(color,.5,.1,{transparent:true,opacity:.08,side:THREE.DoubleSide}),0,1.45,sign*1.8,8.7,2.9,.08);
  const strip=mesh(new THREE.BoxGeometry(8.7,.035,.04),glow,g,0,.16,sign*.15); strip.castShadow=false;
  return g;
}
makeGoal(-23.3,'#25dff2',M.glowC); makeGoal(23.3,'#ff9348',M.glowO);
// grandstand tiers, trusses, lamps, and stylized crowd pixels
for(const side of [-1,1]){
  const x=side*16.1;
  for(let tier=0;tier<5;tier++){
    const y=2.2+tier*.72; box(arena,tier%2?M.dark:M.trim,x,y,0,3.5,.56,45.2);
    for(let n=0;n<40;n++){
      const z=-21.8+n*1.12; const color=[M.cyan,M.orange,M.white,M.trim][(n*7+tier*11+(side===1?2:0))%4];
      box(arena,color,x-side*(.15+(n%3)*.06),y+.32,z,.18,.18,.18);
    }
  }
  for(const z of [-18,0,18]){box(arena,M.trim,side*14.15,3.7,z,.14,7,.14);const lamp=new THREE.PointLight(side<0?'#29dcef':'#ff9b4e',45,21,2);lamp.position.set(side*13.8,7.3,z);scene.add(lamp);}
}
for(let i=0;i<14;i++){const x=-12+i*1.85;box(arena,M.trim,x,6.1,-25,.12,.15,.45);box(arena,M.trim,x,6.1,25,.12,.15,.45);}

function createCar(color, glow, isPlayer){
  const root=new THREE.Group();scene.add(root);
  const shell=new THREE.Group();root.add(shell);
  box(shell,color,0,.57,0,1.72,.56,2.55);
  // tapered hood and trunk accents
  box(shell,color,0,.77,-.73,1.51,.22,.82); box(shell,M.trim,0,.8,.86,1.48,.2,.56);
  const cabin=mesh(new THREE.CylinderGeometry(.63,.76,.98,4,1,false),M.glass,shell,0,1.04,.04,1,1,.95); cabin.rotation.y=Math.PI/4;
  box(shell,M.dark,0,1.09,-.02,1.07,.08,.82);
  box(shell,glow,0,.64,-1.27,1.25,.12,.08);
  box(shell,M.white,-.48,.58,-1.29,.19,.15,.07); box(shell,M.white,.48,.58,-1.29,.19,.15,.07);
  box(shell,M.dark,0,.43,1.31,1.16,.22,.11);
  const wheels=[];
  for(const x of [-.88,.88])for(const z of [-.78,.85]){
    const wh=mesh(new THREE.CylinderGeometry(.37,.37,.24,20),M.black,shell,x,.38,z);wh.rotation.z=Math.PI/2; wheels.push(wh);
    const hub=mesh(new THREE.CylinderGeometry(.18,.18,.255,12),color,shell,x,.38,z);hub.rotation.z=Math.PI/2;
    for(let k=0;k<5;k++){const a=k*Math.PI*2/5;const spoke=box(shell,M.trim,x+Math.sign(x)*.14,.38+Math.sin(a)*.11,z+Math.cos(a)*.11,.025,.025,.17);spoke.rotation.x=a;}
  }
  const boost=new THREE.Group();shell.add(boost);
  for(const x of [-.43,.43]){const plume=mesh(new THREE.ConeGeometry(.18,.9,12),glow,boost,x,.48,1.8);plume.rotation.x=Math.PI/2;}
  boost.visible=false;
  const ring=mesh(new THREE.TorusGeometry(1.05,.025,5,36),glow,shell,0,.09,0);ring.rotation.x=Math.PI/2;ring.scale.set(1,.74,1.3);ring.material=glow;
  const label=box(shell,M.white,0,1.29,.22,.16,.07,.45); label.material=mat(isPlayer?'#42e3f2':'#ffad6e',.3,.25,{emissive:isPlayer?'#137988':'#9a4218',emissiveIntensity:.8});
  return {root,shell,wheels,boost,isPlayer};
}
const player=createCar(M.cyan,M.glowC,true), bot=createCar(M.orange,M.glowO,false);

// Ball: layered panel details, metallic seams, and a subtle orbit glow.
const ballGroup=new THREE.Group();scene.add(ballGroup);
mesh(sphereGeo,M.ball,ballGroup,0,0,0,1,1,1);
for(let i=0;i<12;i++){
  const a=i*Math.PI/6; const p=mesh(new THREE.SphereGeometry(.14,8,6),M.black,ballGroup,Math.cos(a)*.88,Math.sin(a)*.42,Math.sin(a)*.88,.9,.9,.4);
  p.rotation.y=a;
}
const ballHalo=mesh(new THREE.TorusGeometry(1.17,.018,5,48),M.glowC,ballGroup,0,-.82,0);ballHalo.rotation.x=Math.PI/2;
const ballLight=new THREE.PointLight('#d9ffff',1.8,5);ballGroup.add(ballLight);

// Boost pads replenish charge when driven over; large pads deliver a full burst.
const pads=[];
for(const z of [-16,-8,0,8,16])for(const x of [-10.2,0,10.2]){
  const large=x===0&&Math.abs(z)===16;
  const root=new THREE.Group();root.position.set(x,-.025,z);arena.add(root);
  const disk=new THREE.Mesh(new THREE.CylinderGeometry(large?.55:.32,large?.55:.32,.05,28),mat(large?'#50381e':'#254a4e',.4,.25),);root.add(disk);
  const ring=new THREE.Mesh(new THREE.TorusGeometry(large?.46:.27,.035,6,32),large?M.glowO:M.glowC);ring.rotation.x=Math.PI/2;ring.position.y=.045;root.add(ring);
  const core=mesh(new THREE.OctahedronGeometry(large?.19:.12),large?M.glowO:M.glowC,root,0,.2,0); pads.push({x,z,large,root,ring,core,active:true,timer:0});
}

const W=13.1, Z=22.6, keys=new Set(), touch=new Set();
const state={running:false,paused:false,over:false,clock:300,playerScore:0,botScore:0,boost:100,goalTimer:0,resetTimer:0,lastTime:0,camReady:false,sound:true};
const physics={ballV:new THREE.Vector3(),playerV:new THREE.Vector3(),botV:new THREE.Vector3(),ballRadius:1.05,carSpeed:0,botSpeed:0,carHeight:0,carVY:0,botHeight:0,botVY:0,steer:0,particles:[]};
const ui={playerScore:document.querySelector('#playerScore'),botScore:document.querySelector('#botScore'),clock:document.querySelector('#clock'),matchState:document.querySelector('#matchState'),boostFill:document.querySelector('#boostFill'),boostNumber:document.querySelector('#boostNumber'),speedValue:document.querySelector('#speedValue'),message:document.querySelector('#centerMessage'),play:document.querySelector('#playButton'),goal:document.querySelector('#goalFlash'),goalSub:document.querySelector('#goalSub'),pause:document.querySelector('#pauseBadge'),toast:document.querySelector('#toast'),sound:document.querySelector('#soundButton'),soundIcon:document.querySelector('#soundIcon')};

function resize(){const w=canvas.clientWidth,h=canvas.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();}
window.addEventListener('resize',resize);resize();
function startGame(){if(state.over){resetMatch();}state.running=true;state.paused=false;state.lastTime=performance.now();ui.message.classList.add('hidden');ui.pause.classList.remove('visible');ui.matchState.textContent='IN PLAY';ui.matchState.style.color='#d8f6fb';}
function resetPositions(){player.root.position.set(0,0,12);player.root.rotation.set(0,0,0);bot.root.position.set(0,0,-12);bot.root.rotation.set(0,Math.PI,0);physics.playerV.set(0,0,0);physics.botV.set(0,0,0);physics.carSpeed=physics.botSpeed=0;physics.carHeight=physics.botHeight=physics.carVY=physics.botVY=0;ballGroup.position.set(0,1.05,0);physics.ballV.set(0,0,0);player.shell.rotation.set(0,0,0);bot.shell.rotation.set(0,0,0);}
function resetMatch(){state.clock=300;state.playerScore=0;state.botScore=0;state.boost=100;state.over=false;ui.playerScore.textContent='0';ui.botScore.textContent='0';setClock();resetPositions();}
function setClock(){const m=Math.floor(state.clock/60),s=Math.floor(state.clock%60);ui.clock.textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;}
ui.play.addEventListener('click',startGame);
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='Enter'&&!state.running)startGame();if(e.code==='Escape'&&state.running){state.paused=!state.paused;ui.pause.classList.toggle('visible',state.paused);if(!state.paused)state.lastTime=performance.now();}if(e.code==='KeyR'&&state.running){resetPositions();state.boost=100;}});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
for(const b of document.querySelectorAll('[data-control]')){const name=b.dataset.control;const down=e=>{e.preventDefault();touch.add(name);b.classList.add('active');};const up=e=>{e.preventDefault();touch.delete(name);b.classList.remove('active');};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up);}
ui.sound.addEventListener('click',()=>{state.sound=!state.sound;ui.soundIcon.textContent=state.sound?'♫':'♪';ui.sound.style.color=state.sound?'':'#7b8a96';});
const pressed=(...codes)=>codes.some(k=>keys.has(k));

function beep(freq=520,duration=.12,type='sine',volume=.035){if(!state.sound)return;try{const ctx=beep.ctx||(beep.ctx=new AudioContext());if(ctx.state==='suspended')ctx.resume();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(Math.max(80,freq*.55),ctx.currentTime+duration);gain.gain.setValueAtTime(volume,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+duration);}catch{}}
function announce(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(announce.timer);announce.timer=setTimeout(()=>ui.toast.classList.remove('show'),1250);}
function spawnBurst(position,color,count=24,power=5){
  const material=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.95});
  for(let i=0;i<count;i++){
    const o=new THREE.Mesh(new THREE.IcosahedronGeometry(.035+Math.random()*.065,0),material);o.position.copy(position);scene.add(o);
    const v=new THREE.Vector3(Math.random()-.5,Math.random()*.85,Math.random()-.5).normalize().multiplyScalar(power*(.35+Math.random()*.75));
    physics.particles.push({mesh:o,velocity:v,life:.65+Math.random()*.8,maxLife:1.45});
  }
}
function goal(scoredByPlayer){
  if(state.goalTimer>0||state.over)return;
  if(scoredByPlayer){state.playerScore++;ui.playerScore.textContent=state.playerScore;ui.goalSub.textContent=['WHAT A SHOT','TOP CORNER','ABSOLUTE ROCKET'][Math.floor(Math.random()*3)];}
  else{state.botScore++;ui.botScore.textContent=state.botScore;ui.goalSub.textContent='CPU FINDS THE NET';}
  ui.goal.classList.add('show');state.goalTimer=2.7;state.resetTimer=2.7;ui.matchState.textContent='GOAL';ui.matchState.style.color=scoredByPlayer?'#49e6f4':'#ff9b55';
  beep(scoredByPlayer?780:330,.48,'sawtooth',.045);setTimeout(()=>beep(scoredByPlayer?980:250,.35,'triangle',.03),130);
  spawnBurst(ballGroup.position,scoredByPlayer?0x49e6f4:0xff9b55,75,8);
  if(state.playerScore>=3||state.botScore>=3){state.over=true;state.running=false;state.goalTimer=99;setTimeout(()=>{ui.goal.classList.remove('show');ui.message.querySelector('.message-kicker').textContent='FINAL WHISTLE';ui.message.querySelector('.message-title').innerHTML=state.playerScore>state.botScore?'YOU<br><span>TAKE IT!</span>':'THE BOT<br><span>WINS THIS ONE</span>';ui.message.querySelector('p').textContent=`FINAL SCORE  ${state.playerScore} — ${state.botScore}`;ui.play.innerHTML='RUN IT BACK <span>→</span>';ui.message.classList.remove('hidden');ui.matchState.textContent='FINAL';},1600);}
}
function driveCar(car,vel,dt,isPlayer){
  let throttle=0,steer=0,boosting=false,jumping=false;
  if(isPlayer){
    throttle=(pressed('KeyW','ArrowUp')||touch.has('forward')?1:0)-(pressed('KeyS','ArrowDown')||touch.has('reverse')?1:0);
    steer=(pressed('KeyD','ArrowRight')||touch.has('right')?1:0)-(pressed('KeyA','ArrowLeft')||touch.has('left')?1:0);
    boosting=(pressed('Space')||touch.has('boost'))&&state.boost>0&&throttle>=0;
    jumping=(pressed('ShiftLeft','ShiftRight')||touch.has('jump'))&&physics.carHeight<.06;
  } else {
    const ball=ballGroup.position;
    const attackGoal=-Math.sign(car.root.position.z||-1)*21.5;
    const targetX=THREE.MathUtils.clamp(ball.x*.78,-7.3,7.3);
    const targetZ=ball.z+Math.sign(attackGoal-ball.z)*2.5;
    let dx=targetX-car.root.position.x,dz=targetZ-car.root.position.z;
    // Aim behind the ball relative to the bot's attacking direction.
    if(Math.abs(ball.z-car.root.position.z)<7)dz+=ball.z<0?4:-4;
    const targetYaw=Math.atan2(-dx,-dz);
    let diff=Math.atan2(Math.sin(targetYaw-car.root.rotation.y),Math.cos(targetYaw-car.root.rotation.y));
    steer=THREE.MathUtils.clamp(diff*2.15,-1,1);
    const distance=Math.hypot(dx,dz);throttle=distance>2?1:.22;
    if(Math.abs(diff)>1.65)throttle=.2;
    if(distance<3.8&&Math.abs(diff)<.45)throttle=1;
    boosting=distance>9&&Math.abs(diff)<.35;
    jumping=(distance<4&&ball.y>1.8&&Math.random()<dt*.55)&&physics.botHeight<.06;
  }
  const speed=isPlayer?physics.carSpeed:physics.botSpeed;
  const maxSpeed=boosting?25:14.5;
  const turnRate=(1.75+Math.min(Math.abs(speed),11)*.043)*(Math.abs(speed)<.3?.5:1);
  if(Math.abs(speed)>.25)car.root.rotation.y-=steer*turnRate*dt*Math.sign(speed);
  if(throttle!==0){
    const forward=new THREE.Vector3(-Math.sin(car.root.rotation.y),0,-Math.cos(car.root.rotation.y));
    const force=(boosting?30:17.5)*throttle;
    vel.addScaledVector(forward,force*dt);
  }
  vel.multiplyScalar(Math.exp(-(Math.abs(throttle)>.01?1.18:2.05)*dt));
  const speedNow=vel.length();if(speedNow>maxSpeed)vel.multiplyScalar(maxSpeed/speedNow);
  car.root.position.x+=vel.x*dt;car.root.position.z+=vel.z*dt;
  car.root.position.x=THREE.MathUtils.clamp(car.root.position.x,-11.8,11.8);car.root.position.z=THREE.MathUtils.clamp(car.root.position.z,-20.3,20.3);
  car.root.position.y=isPlayer?physics.carHeight:physics.botHeight;
  const h=isPlayer?physics.carHeight:physics.botHeight;
  car.shell.rotation.z=THREE.MathUtils.lerp(car.shell.rotation.z,-steer*Math.min(Math.abs(speed)/15,1)*.075,.14);
  car.shell.rotation.x=THREE.MathUtils.lerp(car.shell.rotation.x,throttle>0&&h===0?-.025:0,.08);
  for(const w of car.wheels)w.rotation.x-=speed*dt*1.4;
  car.boost.visible=boosting&&state.running&&state.goalTimer<=0;
  if(isPlayer){physics.carSpeed=speedNow;physics.steer=steer;if(boosting)state.boost=Math.max(0,state.boost-35*dt);}
  else physics.botSpeed=speedNow;
  if(jumping){if(isPlayer){physics.carVY=7.6;physics.carHeight=.02;}else{physics.botVY=6.3;physics.botHeight=.02;}}
}
function updateVertical(dt){
  for(const [key,vyKey] of [['carHeight','carVY'],['botHeight','botVY']]){
    if(physics[key]>0||physics[vyKey]>0){physics[vyKey]-=19*dt;physics[key]+=physics[vyKey]*dt;if(physics[key]<0){physics[key]=0;physics[vyKey]=0;if(key==='carHeight')beep(150,.08,'sine',.018);}}
  }
}
function updateBall(dt){
  const p=ballGroup.position,v=physics.ballV;
  v.y-=9.8*dt;p.addScaledVector(v,dt);
  if(p.y<1.05){p.y=1.05;if(v.y<-.8){v.y=-v.y*.57;if(Math.abs(v.y)<1.1)v.y=0;}v.x*=.985;v.z*=.985;}
  if(Math.abs(p.x)>12.35){p.x=Math.sign(p.x)*12.35;v.x=-v.x*.72;spawnBurst(p,0x8dd9df,5,1.3);}
  if(p.z < -22.55 && (Math.abs(p.x)>4.4||p.y>3.1)){p.z=-22.55;v.z=Math.abs(v.z)*.76;}
  if(p.z > 22.55 && (Math.abs(p.x)>4.4||p.y>3.1)){p.z=22.55;v.z=-Math.abs(v.z)*.76;}
  // Ball-to-car impacts transfer velocity, with a lively lift on fast shots.
  for(const [car,carVel,height] of [[player,physics.playerV,physics.carHeight],[bot,physics.botV,physics.botHeight]]){
    const dx=p.x-car.root.position.x,dz=p.z-car.root.position.z,dist=Math.hypot(dx,dz),min=1.88;
    if(dist<min&&p.y<height+2.35){
      const nx=dx/(dist||1),nz=dz/(dist||1);p.x=car.root.position.x+nx*min;p.z=car.root.position.z+nz*min;
      const speed=carVel.length();const forwardX=-Math.sin(car.root.rotation.y),forwardZ=-Math.cos(car.root.rotation.y);
      const impact=Math.max(0,carVel.x*nx+carVel.z*nz);
      let hit=Math.max(2.6,impact+Math.max(0,forwardX*nx+forwardZ*nz)*speed*.72);
      v.x+=nx*hit*.54+carVel.x*.3;v.z+=nz*hit*.54+carVel.z*.3;
      if(height>.15||p.y>1.65)v.y=Math.max(v.y,3.8+speed*.19);
